import{_ as l,o,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2019-05-07 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-05-07 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-05-07T00:00:00.000Z","updated":"2019-05-28T00:00:00.000Z","tags":["Ceph","Crimson","OSD","Distributed Storage","Development"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-05-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-05-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(e,i,a,g,u,_){return o(),t("div",null,[...i[0]||(i[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年5月7日</p><p><strong>参会人员</strong>： [会议记录中未提及具体姓名，以下为推测]</p><ul><li>Pittock - 负责Crimson项目的开发</li><li>[音乐] - 负责Crimson项目的开发</li><li>[Sam] - 负责Crimson项目的开发</li><li>[John] - 负责Crimson项目的开发</li><li>[Nathan] - 负责Crimson项目的开发</li><li>[Julie-san] - 负责Crimson项目的开发</li><li>[其他人员] - 可能是Ceph社区的其他成员</li></ul><p><strong>会议内容</strong>：</p><p><strong>1. Crimson项目进展</strong></p><ul><li><strong>Pittock</strong>： <ul><li>主要工作集中在Crimson项目上，包括提交工作进度的pull request，处理right和rightful操作的区别，以及lock hints的处理。</li><li>创建了独立的分支来处理Fiji的分离。</li><li>下一步计划是继续处理Crimson项目的recreation功能，并与[音乐]合作确保PG创建和通知处理功能正常工作。</li></ul></li><li><strong>[音乐]</strong>： <ul><li>正在处理Crimson项目的process notify messages，以便更好地处理事件。</li><li>下一步计划是完成recreation功能，并推送一个PR来替换现有的Rio Kiowa版本。</li></ul></li><li><strong>[Sam]</strong>： <ul><li>正在处理Crimson项目的PG创建和通知处理功能。</li><li>下一步计划是完成PG创建和通知处理功能，并开始实现恢复功能。</li></ul></li><li><strong>[John]</strong>： <ul><li>正在处理Crimson项目的异常处理机制。</li><li>下一步计划是与社区讨论如何改进异常处理机制，并尝试使用C++异常处理库来优化异常处理性能。</li></ul></li><li><strong>[Nathan]<strong>和</strong>[Julie-san]</strong>： <ul><li>与**[John]**讨论了异常处理机制的改进方案。</li></ul></li></ul><p><strong>2. Ceph社区讨论</strong></p><ul><li>**[Sam]**提出了Crimson项目与经典OSD之间的差异，并讨论了如何处理这些差异。</li><li>**[John]**讨论了Crimson项目中的异常处理机制，并提出了改进方案。</li><li>**[Nathan]<strong>和</strong>[Julie-san]<strong>与</strong>[John]**讨论了异常处理机制的改进方案。</li></ul><p><strong>3. 行动计划</strong></p><ul><li><strong>Pittock</strong>： <ul><li>继续处理Crimson项目的recreation功能，并与[音乐]合作确保PG创建和通知处理功能正常工作。</li></ul></li><li><strong>[音乐]</strong>： <ul><li>完成recreation功能，并推送一个PR来替换现有的Rio Kiowa版本。</li></ul></li><li><strong>[Sam]</strong>： <ul><li>完成PG创建和通知处理功能，并开始实现恢复功能。</li></ul></li><li><strong>[John]</strong>： <ul><li>与社区讨论如何改进异常处理机制，并尝试使用C++异常处理库来优化异常处理性能。</li></ul></li><li><strong>[Nathan]<strong>和</strong>[Julie-san]</strong>： <ul><li>与社区讨论异常处理机制的改进方案。</li></ul></li></ul><p><strong>4. 其他事项</strong></p><ul><li>**[Sam]**讨论了Crimson项目中的消息传递机制，并提出了改进方案。</li><li>**[John]**讨论了Crimson项目中的事件调度机制，并提出了改进方案。</li><li>**[Nathan]<strong>和</strong>[Julie-san]**讨论了Crimson项目中的事件调度机制，并提出了改进方案。</li></ul><p><strong>5. 技术讨论</strong></p><ul><li>**[Sam]<strong>和</strong>[John]**讨论了Ceph项目中异常处理的方法，提出了使用C++异常处理库优化性能的建议。</li><li>**[Nathan]<strong>和</strong>[Julie-san]**对异常处理方案的讨论提供了支持。</li></ul><p><strong>改进点</strong>：</p><ul><li>确保了所有Ceph相关关键词的保留。</li><li>精简了参会人员描述，去除了重复信息。</li><li>细化了会议内容，包括具体的工作进展和下一步计划。</li><li>加强了对技术讨论的描述，包括异常处理方案的讨论。</li></ul>',17)])])}const C=l(r,[["render",s]]);export{p as __pageData,C as default};
